read=lambda n:json.loads((B/(n+'.json')).read_text());reports={n:read(n)for n in ['physics-tests','item-tests','surface-tests','world-tests','browser-tests','offline-tests','unchanged-renders','scope-tests','comparison-report','release-smoke','terrain-tests','grand-prix-tests','grand-prix-browser-tests']}
for n,r in reports.items():assert r['status']=='passed',n
raw=H.read_bytes();sha=lambda x:hashlib.sha256(x).hexdigest();metrics=read('asset-metrics');assert sha(raw)==metrics['html_sha256'];assert reports['release-smoke']['html_sha256']==sha(raw);assert raw==Path('/tmp/blokraya-6g/candidate.html').read_bytes()
metrics.update({'under_25_decimal_MB':len(raw)<25000000,'reports':{n:len(r.get('checks',[]))for n,r in reports.items()},'teacher_export_bytes':reports['offline-tests']['export_bytes'],'offline_asset_HTTP_requests':len(reports['offline-tests']['assetRequests']),'direct_file_note':read('direct-file-tests').get('reason'),'release_status':'Ready for visual review; reference accuracy and direct file navigation have documented limitations.'})
notes='BLOKRAYA — STAGE 10 BROMO: VOLCANO CHALLENGE (6G)\n\nEkstrak ZIP lalu buka blokraya-stage10-bromo.html pada browser modern dengan WebGL. Seluruh aset tertanam. Gunakan browser/profil/origin yang sama untuk membaca data lokal lama. Mode Siswa tanpa PIN; Mode Guru memakai PIN lokal. Interaksi diperlukan untuk audio.\n\nSepuluh arena playable dan Grand Prix Nusantara tersedia setelah seluruh adapter world terdaftar. Kalbar Klasik tetap tiga arena awal. Tidak memberikan token/unlock atau profil QA pada distribusi.\n\nLintasan vulkanik fiktif 820,41 m, lautan pasir, kawah terbuka dengan lereng beralur, kerucut pendamping, dinding kaldera, bukit pasir, basalt, kepulan blocky statis, horizon pagi dan dek pandang kecil. Ini interpretasi stylized, bukan rekonstruksi geografis/aktivitas balap di kawasan Bromo sebenarnya. Referensi web ditolak403; proporsi/detail belum diverifikasi dari foto.\n\nGeometri prosedural dibatch dengan material bersama dan satu tekstur papan kecil. Gradient/awan/fog lama dipertahankan tanpa shader langit/point light baru. Physics, AI, buff, ketuntasan akademik dan storage lama tetap.\n\nUji Grand Prix UI menggunakan fixture posisi menuju kuis/finish; bukan klaim sepuluh balapan manual penuh. Driver simulasi menyelesaikan lap nyata seluruh sepuluh lintasan secara terpisah. Ronde terakhir gagal/ulang/lolos, rollback poin dan rekap juara diuji.\n\nOffline lulus dengan jaringan browser dimatikan dan dokumen lokal disuplai harness localhost, tanpa request aset HTTP/CDN. file:// benar-benar dicoba tetapi diblokir administrator cloud. Perlu verifikasi browser target; tidak menambahkan server wajib/fetch aset lokal. HP fisik/FPS/frame time/memori belum diukur.\n\nKontrol: A/D/panah, W/S gas/rem, C drift, Shift jump, E/Spasi buff, Q/1/2 slot, P/Esc jeda, serta kontrol sentuh. Semua simulasi berhenti ketika soal/jeda. Nilai akademik terpisah dari posisi balapan.\n\nReview ZIP memuat builder JavaScript editable, lintasan, metadata, screenshot asli serta laporan. Build memerlukan checkout baseline Bali, lihat README. Blender tersedia; geometri prosedural dipilih agar ringan tanpa GLB environment baru.\n\nTidak merge, mengubah index.html atau deployment. Pekerjaan berhenti pada6G.\n'
for kind in ['playable','review']:
 dest=R/f'blokraya-stage10-bromo-{kind}.zip'
 with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED,compresslevel=9)as z:
  z.write(H,H.name);z.writestr('MULAI.txt',notes)
  if kind=='review':
   for f in sorted(B.rglob('*')):
    if f.is_file()and '__pycache__'not in f.parts and f.name!='release-metrics.json':z.write(f,'stage10-bromo/'+f.relative_to(B).as_posix())
   z.writestr('stage10-bromo/release-metrics.json',json.dumps({**metrics,'review_self_hash_omitted':True,'review_self_hash_note':'The full review ZIP hash lives in the repository release-metrics.json; an archive cannot contain its own final hash.'},indent=2))
 with zipfile.ZipFile(dest)as z:assert z.testzip()is None;assert z.read(H.name)==raw;entries=len(z.namelist())
 metrics[kind+'_zip']={'file':dest.name,'bytes':dest.stat().st_size,'sha256':sha(dest.read_bytes()),'crc_ok':True,'html_identical':True,'entries':entries}
(B/'release-metrics.json').write_text(json.dumps(metrics,indent=2));print(json.dumps({k:metrics[k]for k in ['html_bytes','growth_bytes','html_sha256','playable_zip','review_zip']},indent=2))
